      "flow": [
        {
          "action": "乐止，贾妃自座上起身。"
        },
        {
          "action": "贾母、王夫人跪止不迭。"
        },
        {
          "action": "贾妃一手搀贾母、一手搀王夫人，三人相对呜咽对泣。"
        },
        {
          "action": "邢夫人、李纨、王熙凤与迎、探、惜三姊妹在旁围绕，垂泪无言。"
        },
        {
          "action": "贾妃忍悲强笑。"
        },
        {
          "speaker": "P01",
          "line": "当日既送我到那不得见人的去处，好容易今日回家娘儿们一会，反倒哭起来。",
          "mode": "spoken",
          "delivery": "强笑"
        },
        {
          "speaker": "P01",
          "line": "一会子我就要走了，又不知多晚才来了！",
          "mode": "spoken",
          "delivery": "哽咽"
        },
        {
          "action": "王熙凤上来解劝，贾母、王夫人让贾妃归座。"
        },
        {
          "speaker": "P01",
          "line": "薛姨妈、宝钗、黛玉为何不见？",
          "mode": "spoken",
          "delivery": "问"
        },
        {
          "speaker": "P03",
          "line": "外眷无职，未敢擅入。",
          "mode": "spoken",
          "delivery": "起身启奏"
        },
        {
          "action": "贾妃听了，忙命快请。"
        },
        {
          "action": "贾政至帘外问安，贾妃垂帘还礼。"
        },
        {
          "speaker": "P04",
          "line": "田舍之家，虽齑盐布帛，终能聚天伦之乐。",
          "mode": "spoken",
          "delivery": "隔帘含泪"
        },
        {
          "speaker": "P04",
          "line": "今虽富贵已极，骨肉各方，然终无意趣！",
          "mode": "spoken",
          "delivery": "隔帘含泪"
        },
        {
          "speaker": "P04",
          "line": "臣只业业兢兢，恪守本职；请贵妃自加珍爱，莫念老拙。",
          "mode": "spoken",
          "delivery": "含泪"
        },
        {
          "speaker": "P01",
          "line": "只以国事为重，暇时保养，切勿记念。",
          "mode": "spoken",
          "delivery": "隔帘"
        },
        {
          "speaker": "P04",
          "line": "园中亭台轩馆，皆是宝玉题的；若有一二可看的，请赐名。",
          "mode": "spoken",
          "delivery": "启奏"
        },
        {
          "speaker": "P01",
          "line": "果进益了。",
          "mode": "spoken",
          "delivery": "含笑"
        },
        {
          "action": "贾政退出。"
        },
        {
          "speaker": "P01",
          "line": "宝玉为何不进见？",
          "mode": "spoken",
          "delivery": "问"
        },
        {
          "speaker": "P02",
          "line": "无谕，外男不敢擅入。",
          "mode": "spoken",
          "delivery": "启奏"
        },
        {
          "action": "贾妃命引进来，宝玉入内，先行国礼毕。"
        },
        {
          "action": "贾妃命宝玉进前，揽于怀内，抚其头颈。"
        },
        {
          "speaker": "P01",
          "line": "比先竟长了好些……",
          "mode": "spoken",
          "delivery": "笑"
        },
        {
          "action": "一语未终，贾妃泪如雨下。"
        },
        {
          "speaker": "P06",
          "line": "筵宴齐备，请贵妃游幸。",
          "mode": "spoken",
          "delivery": "启奏"
        }
      ]
    },
    {
      "sceneId": "L02",
      "characters": [
        "P01",
        "P02",
        "P03",
        "P05",
        "P06"
      ],
      "flow": [
        {
          "action": "贾妃与贾母、王夫人起身，命宝玉导引，同至园门前。"
        },
        {
          "action": "园中灯光火树，贾妃与贾母、王夫人入园，遍游“有凤来仪”“杏帘在望”等处。"
        },
        {
          "speaker": "P01",
          "line": "以后不可太奢，此皆过分之极。",
          "mode": "spoken",
          "delivery": "劝"
        },
        {
          "action": "至正殿，免礼归座，大开筵宴。"
        },
        {
          "action": "贾母、王夫人在下相陪，王熙凤亲捧羹把盏。"
        }
      ]
    }
  ]
}
